`,e.exports.jsxs(s.p,{children:["Welcome to Lab 77! As you might know, video, audio, and even electrocardiograms of your heart are all innately ",e.exports.jsx(s.strong,{children:"continuous signals"}),". However, computers can only store and process a finite collection of values, which means that those continuous signals must be somehow converted into ",e.exports.jsx(s.strong,{children:"discrete signals"})," (a quick reminder of their differences ",e.exports.jsx(s.a,{href:"https://en.wikipedia.org/wiki/Discrete_time_and_continuous_time",target:"_blank",rel:"noopener noreferrer",children:"here"}),")."]}),`
